import type { CollectionKit, CollectionKitProduct, CollectionKitSection } from "@/data/collection-kits";

const COLLECTION_KIT_PLACEHOLDER_IMAGE = "/collections/amazon-beauty-toolkit/product-placeholder.svg";

const P = (
  id: string,
  name: string,
  description: string,
  href: string,
  note?: string,
  image?: string,
  priceLabel?: string,
  mrpLabel?: string,
  badge?: string,
): CollectionKitProduct => ({
  id,
  name,
  badge: badge ?? "Vetted pick",
  description,
  image: image ?? COLLECTION_KIT_PLACEHOLDER_IMAGE,
  ...(note ? { note } : {}),
  href,
  ...(priceLabel ? { priceLabel } : {}),
  ...(mrpLabel ? { mrpLabel } : {}),
});

const S = (
  slug: string,
  title: string,
  stepLabel: string,
  shortIntro: string,
  products: CollectionKitProduct[],
): CollectionKitSection => ({ slug, title, stepLabel, shortIntro, products });

